void full_native_state() {
  Ocel source;
  const auto raw=bytes("00ffeda080");
  source.events={{"e0","A","later",{{raw,-0.0}}},
                 {"e1","B","earlier",{{"dup",nullptr},{"dup",raw}}}};
  source.objects={{raw,"T",{{raw,std::numeric_limits<double>::quiet_NaN()},
                             {"dup",nullptr},{"dup",raw}}},
                  {"other","U",{{raw,true}}}, {"unused","T",{{raw,nullptr}}}};
  source.relations={{"e0",raw,"q"},{"e0","other",raw},
                    {"e1","other","q"},{"e1","other","duplicate"}};
  source.o2o={{raw,"other","link"},{raw,raw,raw},{raw,raw,raw}};
  source.e2e={{"e0","e1","link"},{"e0","e0",raw},{"e0","e0",raw}};
  source.object_changes={{raw,"T","later",raw,raw},
                          {"other","U","later","value",-0.0},
                          {"unused","T","later","value",nullptr}};
  source.globals={{raw,raw},{"bool",true},{"integer",std::int64_t{-7}}};
  source.event_type_attributes={{"unused",{{raw,"string"}}}};
  source.object_type_attributes={{"T",{{raw,"string"}}},{"unused",{{raw,"time"}}}};
  source.table_columns.events=std::vector<std::string>{};
  source.table_columns.objects=std::vector<std::string>{raw,"dup","dup"};
  source.table_columns.relations=std::nullopt;
  const auto before=serialize_oc_playout_workbench_ocel_json(source);
  auto expected=source;
  expected.events.pop_back();
  expected.objects.resize(1);
  expected.relations.resize(1);
  expected.o2o.erase(expected.o2o.begin());
  expected.e2e.erase(expected.e2e.begin());
  expected.object_changes.resize(1);
  auto result=filter_ocel_object_attribute_exact(source,raw,
      {std::numeric_limits<double>::quiet_NaN()});
  assert(serialize_oc_playout_workbench_ocel_json(result)==
         serialize_oc_playout_workbench_ocel_json(expected));
  result.globals[raw]=std::string("independent");
  result.objects[0].attributes.clear();
  assert(serialize_oc_playout_workbench_ocel_json(source)==before);
  auto dated=source;
  dated.objects[0].attributes.push_back({"date",std::string("NaT")});
  dated.objects[1].attributes.push_back({"date",std::string("2026-01-01T00:00:00.000000001Z")});
  dated.objects[2].attributes.push_back({"date",std::string("2026-01-01T00:00:00Z")});
  for (auto& object:dated.objects) object.attributes.push_back({"literal date",object.id=="other"
      ? std::string("2026-01-01T00:00:00.000000001Z") : std::string("NaT")});
  dated.object_type_attributes["T"]["date"]="time";
  dated.object_type_attributes["U"]["date"]="datetime";
  dated.object_type_attributes["T"]["literal date"]="string";
  dated.object_type_attributes["U"]["literal date"]="string";
  dated.table_columns.objects->push_back("date");
  dated.table_columns.objects->push_back("literal date");
  const auto dated_before=serialize_oc_playout_workbench_ocel_json(dated);
  const auto instant=datetime("2026-01-01T00:00:00.000000001Z");
  const auto nat=filter_ocel_object_attribute_exact(dated,"date",{OcelObjectAttributeNaT{}});
  assert(nat.objects.size()==1 && nat.objects[0].id==raw);
  assert(filter_ocel_object_attribute_exact(dated,"date",{nullptr}).objects.empty());
  assert(filter_ocel_object_attribute_exact(dated,"date",
      {std::numeric_limits<double>::quiet_NaN()}).objects.empty());
  const auto time=filter_ocel_object_attribute_exact(dated,"date",{instant});
  assert(time.objects.size()==1 && time.objects[0].id=="other");
  assert(filter_ocel_object_attribute_exact(dated,"literal date",{instant}).objects.empty());
  const auto explicit_time=filter_ocel_object_attribute_exact(dated,"literal date",{instant},true,
      OcelObjectAttributeColumnKind::kTimestamp);
  assert(explicit_time.objects.size()==1 && explicit_time.objects[0].id=="other");
  const auto explicit_scalar=filter_ocel_object_attribute_exact(dated,"date",
      {std::string("2026-01-01T00:00:00.000000001Z")},true,OcelObjectAttributeColumnKind::kScalar);
  assert(explicit_scalar.objects.size()==1 && explicit_scalar.objects[0].id=="other");
  assert(serialize_oc_playout_workbench_ocel_json(dated)==dated_before);
}
